294	  <script>
295	    const canvas = document.getElementById('heatmap');
296	    const ctx = canvas.getContext('2d');
297	    const tooltip = document.getElementById('tooltip');
298	
299	    // Protocol Shield: Detect CORS-blocked file access
300	    if (window.location.protocol === 'file:') {
301	      const shield = document.createElement('div');
302	      shield.style.cssText = "position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(10,10,15,0.95); z-index:10000; display:flex; flex-direction:column; align-items:center; justify-content:center; padding:40px; text-align:center; color:#ff4d4d; border:2px solid #ff4d4d;";
303	      shield.innerHTML = `
304	        <h1 style="color:#ff4d4d">⚠️ PROTOCOL BLOCKAGE DETECTED</h1>
305	        <p style="font-size:18px; color:#fff; margin:20px 0;">The Sovereign Engine cannot fetch logical chunks via <b>file://</b> due to browser CORS security.</p>
306	        <p style="font-size:16px; color:#51ffff;">You must access the Unified Radar via the Sovereign Pulse Server:</p>
307	        <a href="${window.location.origin}/heatmap.html" style="background:#51ffff; color:#000; padding:15px 30px; border-radius:5px; font-weight:bold; text-decoration:none; margin-top:20px; font-size:20px;">OPEN SOVEREIGN PULSE</a>
308	        <p style="margin-top:30px; font-size:12px; color:#666;">(Alternatively, use the "Load File" button to manually ingest a mapsquare JSON)</p>
309	    `;
310	      document.body.appendChild(shield);
311	    }
312	
313	    let currentData = null;
314	    let currentScale = 8;
315	    let currentSize = 66; // NXT default, adapted per-chunk in render()
316	    let tileGrid = null; // [x][z] = { collision, height, overlay, underlay }
317	    let objectGrid = null; // [x][z] = [objectDef, ...]
318	    let layers = { npcs: true, zones: true, quests: true, terrain: true, height: false };
319	    let varbitState = {}; // id -> value
320	    let ws = null;
321	
322	    function connectWS() {
323	      const wsUrl = `ws://${window.location.hostname}:8788`;
324	      ws = new WebSocket(wsUrl);
325	      ws.onmessage = (e) => {
326	        const data = JSON.parse(e.data);
327	        if (data.type === 'result' && data.value && data.value.type === 'LIVE_rsmv') {
328	          handleLiversmv(data.value);
329	        }
330	      };
331	      ws.onopen = () => { document.getElementById('status').textContent = 'Pulse Link: ACTIVE'; };
332	      ws.onclose = () => {
333	        document.getElementById('status').textContent = 'Pulse Link: LOST';
334	        setTimeout(connectWS, 2000);
335	      };
336	    }
337	    connectWS();
338	
339	    function liveExtract() {
340	      if (!ws || ws.readyState !== WebSocket.OPEN) {
341	        alert("Switchboard Bridge not connected!");
342	        return;
343	      }
344	      const cx = parseInt(document.getElementById('cx').value);
345	      const cz = parseInt(document.getElementById('cz').value);
346	      const plane = parseInt(document.getElementById('plane').value);
347	
348	      const worldX = cx * 64;
349	      const worldZ = cz * 64;
350	
351	      document.getElementById('status').textContent = `Requesting Live Extraction at [${worldX}, ${worldZ}]...`;
352	      ws.send(JSON.stringify({ type: 'command', intent: `GET_LIVE_rsmv ${worldX} ${worldZ} ${plane}` }));
353	    }
354	
355	    function handleLiversmv(liveData) {
356	      document.getElementById('status').textContent = `Live Data Received for [${liveData.x}, ${liveData.z}]`;
357	
358	      // Convert Live format to heatmap format
359	      const size = liveData.xsize;
360	      const tileFlags = [];
361	      const entriesPerTile = 5; // [h00, h01, h10, h11, col3]
362	
363	      for (let i = 0; i < size * size; i++) {
364	        const col3 = liveData.data[i * entriesPerTile + 4];
365	        const h00 = liveData.data[i * entriesPerTile + 0];
366	
367	        // Map base-3 col3 to bitmask (bit 1 = blocked)
368	        const centerVal = col3 % 3;
369	        const collision = (centerVal === 1 || centerVal === 2) ? 2 : 0;
370	
371	        tileFlags.push({
372	          collision: collision,
373	          height: h00,
374	          x: Math.floor(i / size),
375	          z: i % size
376	        });
377	      }
378	
379	      const mappedData = {
380	        tileFlags: tileFlags,
381	        worldX: liveData.x,
382	        worldZ: liveData.z,
383	        chunkX: liveData.x >> 6,
384	        chunkZ: liveData.z >> 6,
385	        objectDefs: {},
386	        objects: []
387	      };
388	
389	      render(mappedData, 0, currentScale);
390	    }
391	
392	    function toggleLayer(name) {
393	      layers[name] = !layers[name];
394	      document.getElementById(`btn-${name}`).classList.toggle('active');
395	      if (currentData) render(currentData, parseInt(document.getElementById('plane').value), currentScale);
396	    }
397	
398	    function updateVarbit() {
399	      const id = document.getElementById('varId').value;
400	      const val = parseInt(document.getElementById('varVal').value);
401	      if (id !== "") varbitState[id] = val;
402	      if (currentData) render(currentData, parseInt(document.getElementById('plane').value), currentScale);
403	    }
404	
405	    // Collision flag → color mapping (heat/integrity)
406	    function getCollisionInfo(flags, engine) {
407	      if (engine === 'NXT') {
408	        return {
409	          blocked: !!(flags & 2),
410	          water: !!(flags & 16),
411	          bridge: !!(flags & 4),
412	          roof: !!(flags & 8)
413	        };
414	      } else {
415	        // RS3 Classic Settings
416	        return {
417	          blocked: !!(flags & 1),
418	          water: false, // RS3 uses separate type field for water
419	          bridge: !!(flags & 2),
420	          roof: !!(flags & 4)
421	        };
422	      }
423	    }
424	
425	    function collisionColor(flags, engine) {
426	      const info = getCollisionInfo(flags, engine);
427	      if (info.blocked) return [220, 50, 47, 255]; // Red
428	      if (info.roof) return [20, 20, 30, 255];    // Dark Grey
429	
430	      if (flags === 0) return [13, 17, 23, 255];  // walkable
431	      return [26, 107, 74, 255]; // low heat
432	    }
433	
434	    function objectColor() {
435	      return [108, 113, 196, 200]; // purple overlay
436	    }
437	
438	    function render(data, planeIdx, scale) {
439	      if (!data || !data.tileFlags) return;
440	
441	      currentData = data;
442	      currentScale = scale;
443	      const engine = document.getElementById('engineMode').value;
444	
445	      // ADAPTIVE GRID SIZING (RS3 64x64 vs NXT 66x66)
446	      const tilesTotal = data.tileFlags.length;
447	      const size = tilesTotal >= 17424 ? 66 : 64;
448	      currentSize = size;
449	      const tilesPerPlane = size * size;
450	
451	      canvas.width = size * scale;
452	      canvas.height = size * scale;
453	
454	      tileGrid = Array.from({ length: size }, () => Array.from({ length: size }, () => null));
455	      objectGrid = Array.from({ length: size }, () => Array.from({ length: size }, () => []));
456	
457	      const isComposite = document.getElementById('compositeMode').checked;
458	      const startIdx = planeIdx * tilesPerPlane;
459	
460	      if (isComposite) {
461	        for (let i = 0; i < tilesPerPlane; i++) {
462	          const tx = Math.floor(i / size);
463	          const tz = i % size;
464	          let compositeCollision = 0;
465	          for (let p = 0; p < 4; p++) {
466	            const tile = data.tileFlags[p * tilesPerPlane + i];
467	            if (tile) compositeCollision |= tile.collision;
468	          }
469	          tileGrid[tx][tz] = { collision: compositeCollision };
470	        }
471	      } else {
472	        for (let i = 0; i < tilesPerPlane; i++) {
473	          const tile = data.tileFlags[startIdx + i];
474	          const tx = Math.floor(i / size);
475	          const tz = i % size;
476	          if (tx < size && tz < size) tileGrid[tx][tz] = tile;
477	        }
478	      }
479	
480	      // Object placements for this plane
481	      if (data.objects) {
482	        for (const obj of data.objects) {
483	          const pMatch = isComposite || obj.plane === planeIdx;
484	          if (pMatch && obj.x < size && obj.z < size) {
485	            const def = data.objectDefs?.[obj.objectId];
486	            const actions = def?.actions || [];
487	            const isPortal = actions.some(a => ["Climb-down", "Climb-up", "Enter", "Open-trapdoor", "Open", "Leave"].includes(a));
488	
489	            // 🧬 Sovereign Physics Override (Varbit Collision Masking)
490	            if (def && varbitState[obj.objectId.toString()] === 1) {
491	              if (tileGrid[obj.x][obj.z]) tileGrid[obj.x][obj.z].collision = 0;
492	            }
493	
494	            objectGrid[obj.x][obj.z].push({
495	              ...obj,
496	              name: def?.name || null,
497	              actions: actions,
498	              solid: def?.solid ?? null,
499	              isHotspot: actions.includes("Build"),
500	              isPortal: isPortal
501	            });
502	          }
503	        }
504	      }
505	
506	      // Render
507	      const imgData = ctx.createImageData(canvas.width, canvas.height);
508	
509	      for (let x = 0; x < size; x++) {
510	        for (let z = 0; z < size; z++) {
511	          const tile = tileGrid[x][z];
512	          let color;
513	
514	          if (!tile) {
515	            color = [5, 5, 10, 255]; // no data
516	          } else {
517	            // 1. Terrain Base Pass
518	            if (layers.terrain && tile.underlaycolor) {
519	              // underlaycolor is often ushort HSL or packed. 
520	              // Simple expansion for heatmap visual:
521	              const r = (tile.underlaycolor >> 10) & 0x1F;
522	              const g = (tile.underlaycolor >> 5) & 0x1F;
523	              const b = tile.underlaycolor & 0x1F;
524	              color = [r * 8, g * 8, b * 8, 255];
525	            } else {
526	              color = collisionColor(tile.collision, engine);
527	            }
528	
529	            // 2. Height Adjustment (Shading)
530	            if (layers.height && tile.height) {
531	              const h = tile.height / (engine === 'NXT' ? 256 : 1); // NXT is higher res
532	              const shade = Math.min(255, 120 + h);
533	              color = [
534	                Math.round(color[0] * (shade / 255)),
535	                Math.round(color[1] * (shade / 255)),
536	                Math.round(color[2] * (shade / 255)),
537	                255
538	              ];
539	            }
540	
541	            // 3. TRANSPARENT WATER PASS
542	            const info = getCollisionInfo(tile.collision, engine);
543	            if (info.water || (engine === 'RS3' && tile.type === 3)) {
544	              const hasBridge = info.bridge || objectGrid[x][z].some(o => o.isPortal);
545	              if (!hasBridge) {
546	                // Indigo/Cyan Tint for water
547	                color = [0, 80, 200, 115]; // 45% opaque blue
548	              }
549	            }
550	          }
551	
552	          // Object overlay
553	          if (objectGrid[x][z].length > 0) {
554	            const oc = objectColor();
555	            // Blend
556	            const alpha = oc[3] / 255;
557	            color = [
558	              Math.round(color[0] * (1 - alpha) + oc[0] * alpha),
559	              Math.round(color[1] * (1 - alpha) + oc[1] * alpha),
560	              Math.round(color[2] * (1 - alpha) + oc[2] * alpha),
561	              255
562	            ];
563	          }
564	
565	          // Paint scaled pixels
566	          for (let dx = 0; dx < scale; dx++) {
567	            for (let dz = 0; dz < scale; dz++) {
