        if (reconciliation.consensus !== 'STABLE') {
            logger.warn({
                tile: reconciliation.tile,
                consensus: reconciliation.consensus,
                uncertainty: reconciliation.uncertainty
            }, 'Reality Disagreement Broadcasted to Globe.');
        }
    }

