215	        if (!this.db) return { ok: false, error: new Error('Database not initialized') };
216	
217	        try {
218	            let rows = this.db.prepare('SELECT * FROM lessons ORDER BY createdAt DESC LIMIT 1000').all() as LessonRow[];
219	
