221	            for (const sat of this.satellites) {
222	                try {
223	                    const satRows = sat.prepare('SELECT * FROM lessons ORDER BY createdAt DESC LIMIT 1000').all() as LessonRow[];
224	                    rows = rows.concat(satRows);
