240	                // --- Phase 25: Cognitive Evolution Logic ---
241	                const now = ClockAuthorityRegistry.resolveTime(ClockDomain.INFERENCE, 'VectorDB');
242	                const ageSeconds = (now - row.createdAt) / 1000;
243	                const tau = 7 * 24 * 60 * 60; // 7-day half-life for memory decay (in seconds)
244	                const temporalDecay = Math.exp(-ageSeconds / tau);
245	                
246	                // Reinforcement Boost: usageCount increases relevance physics
247	                const usageBoost = Math.min(row.usageCount * 0.05, 0.5); // Cap boost at +0.5
248	                
249	                let finalSimilarity = (similarityValue * temporalDecay) + usageBoost;
250	
251	                if (projectId && row.projectId === projectId) finalSimilarity += 0.1;
252	
253	                if (domainNamespace && row.domainNamespace && row.domainNamespace !== 'global') {
254	                    if (row.domainNamespace !== domainNamespace) {
255	                        finalSimilarity -= 0.3;
256	                    } else {
257	                        finalSimilarity += 0.15;
258	                    }
259	                }
260	
261	                const lesson: Lesson & { similarity: number } = {
262	                    id: String(row.id),
263	                    text: String(row.text),
264	                    embedding,
265	                    sessionId: row.sessionId ? String(row.sessionId) : undefined,
266	                    projectId: String(row.projectId || 'global'),
