272	                    similarity: finalSimilarity,
273	                    hash: row.hash ? String(row.hash) : undefined,
274	                    type: row.type ? String(row.type) : 'lesson'
275	                };
276	                return lesson;
277	            }).filter((l): l is (Lesson & { similarity: number }) => l !== null);
