452	    private cosineSimilarity(a: Float32Array, b: Float32Array): number {
453	        let dotProduct = 0;
454	        let normA = 0;
455	        let normB = 0;
456	        const len = Math.min(a.length, b.length);
457	        for (let i = 0; i < len; i++) {
458	            dotProduct += (a[i] ?? 0) * (b[i] ?? 0);
459	            normA += (a[i] ?? 0) * (a[i] ?? 0);
460	            normB += (b[i] ?? 0) * (b[i] ?? 0);
461	        }
462	        const den = Math.sqrt(normA) * Math.sqrt(normB);
463	        return den === 0 ? 0 : dotProduct / den;
464	    }
