    private generateSessionId(): string {
        const now = new Date();
        const dateStr = now.toISOString().split('T')[0]!.replace(/-/g, '');
        const timeStr = now.toTimeString().split(' ')[0]!.replace(/:/g, '');
        return `pog2_${dateStr}_${timeStr}_${Math.random().toString(36).substring(2, 6)}`;
    }

